int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r = 0;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int (*init)(struct kvm_device *dev);

	mutex_lock(&kvm->lock);

	if (cd->type >= KVM_DEV_TYPE_MAX ||
	    !kvm_dev_ops[cd->type]) {
		r = -EINVAL;
		goto out;
	}

	ops = kvm_dev_ops[cd->type];
	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev) {
		r = -ENOMEM;
		goto out;
	}

	if (cd->flags & KVM_CREATE_DEVICE_TEST) {
		kfree(dev);
		dev = NULL;
		goto done;
	}

	dev->ops = ops;
	dev->kvm = kvm;
	INIT_LIST_HEAD(&dev->list);
	list_add(&dev->list, &kvm->devices);

	init = ops->init;
	if (init) {
		r = init(dev);
		if (r)
			goto fail;
	}

	dev->fd = anon_inode_get_fd(ops->name);
	if (dev->fd < 0) {
		r = dev->fd;
		goto fail;
	}

done:
	cd->fd = dev->fd;
out:
	mutex_unlock(&kvm->lock);
	return r;

fail:
	kvm_remove_device(dev);
	if (ops->destroy)
		ops->destroy(dev);
	kfree(dev);
	goto out;
}

int kvm_vm_ioctl_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int r = -EINVAL;
	int fd;

	if (!cd->type)
		goto out;

	mutex_lock(&kvm->lock);
	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		goto unlock;

	if (cd->flags & KVM_CREATE_DEVICE_TEST) {
		r = 0;
		goto unlock;
	}

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		goto unlock;

	dev->ops = ops;
	dev->kvm = kvm;
	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	r = ops->init(dev);
	if (r)
		goto unlock;

	fd = kvm_dev_ioctl_create_device(kvm, dev);
	if (fd < 0)
		goto unlock;

	cd->fd = fd;
	return 0;

unlock:
	mutex_unlock(&kvm->lock);
out:
	return r;
}

#include <linux/kvm.h>
#include <linux/slab.h>
#include <linux/list.h>

int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device *dev;
	const struct kvm_device_ops *ops;
	int r = -EINVAL;

	ops = kvm_dev_ops_find(cd->type);
	if (!ops)
		goto out;

	if (cd->flags & KVM_CREATE_DEVICE_TEST) {
		r = 0;
		goto out;
	}

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev) {
		r = -ENOMEM;
		goto out;
	}

	kvm_get_kvm(kvm);
	dev->kvm = kvm;
	dev->ops = ops;
	mutex_lock(&kvm->lock);
	r = ops->create(dev);
	if (r)
		goto unlock;

	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init) {
		r = ops->init(dev);
		if (r)
			goto init_failed;
	}

	dev->fd = anon_inode_getfd("kvm-device", &kvm_device_fops, dev);
	if (dev->fd < 0) {
		r = dev->fd;
		goto init_failed;
	}

	cd->fd = dev->fd;
	return 0;

init_failed:
	ops->destroy(dev);
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
out:
	return r;
}

int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_dev_get_ops(cd->type);
	if (!ops)
		return -ENODEV;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	dev->ops = ops;
	dev->kvm = kvm;
	mutex_lock(&kvm->lock);
	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	r = ops->create(dev, cd->flags);
	if (r)
		goto fail_unlock;

	if (ops->init) {
		r = ops->init(dev);
		if (r)
			goto fail_unlock;
	}

	cd->fd = get_ksysfs_fd(dev);
	if (cd->fd < 0) {
		r = cd->fd;
		goto fail_unlock;
	}

	return 0;

fail_unlock:
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
	ops->destroy(dev);
	kfree(dev);
	return r;
}

int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r;
	struct kvm_device *dev;
	const struct kvm_device_ops *ops;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_lock(kvm);
	r = -EEXIST;
	list_for_each_entry(dev, &kvm->devices, list)
		if (dev->id == cd->id)
			goto out;
	r = 0;

	dev->kvm = kvm;
	dev->id = cd->id;
	dev->ops = ops;
	list_add(&dev->list, &kvm->devices);
	kvm_unlock(kvm);

	if (ops->init_dev) {
		r = ops->init_dev(dev);
		if (r)
			goto fail;
	}

	dev->fd = kvm_device_get_file_descriptor(dev);
	if (dev->fd < 0) {
		r = dev->fd;
		goto fail;
	}

	cd->fd = dev->fd;
	return 0;

fail:
	kvm_lock(kvm);
	list_del(&dev->list);
	kvm_unlock(kvm);
	if (ops->destroy)
		ops->destroy(dev);
	kfree(dev);
	return r;
}
